package studio.jiayu.neoagent;
import java.util.*;
public class PurchaseStateTest {
 static int n;static void yes(boolean b,String why){if(!b)throw new AssertionError(why);n++;}static void reject(Runnable call){boolean denied=false;try{call.run();}catch(IllegalStateException expected){denied=true;}yes(denied,"unsafe transition accepted");}
 static PurchaseFacts order(){return PurchaseFacts.read(Arrays.asList("确认订单","商品：百洁布","数量1","实付¥4.99(含运费)","收货地址：本地合成收件地址"),false);}
 static PurchaseFacts receipt(String id,long at,boolean paid){PurchaseFacts f=order();f.confirmPage=false;f.submitted=!paid;f.paid=paid;f.orderKey=PurchaseFacts.digest(id);f.orderAt=at;return f;}
 public static void main(String[] args){PurchasePolicy.Grant grant=PurchasePolicy.grant(PurchasePolicyTest.USER,"com.taobao.taobao");PurchaseState s=new PurchaseState();long now=1000000;s.armSubmit("run1","com.taobao.taobao",grant,order(),now);yes(s.pending()&&!s.paidFor("run1"),"pending counted as success");reject(()->s.armSubmit("run1","com.taobao.taobao",grant,order(),now));reject(()->s.armSubmit("run2","com.jingdong.app.mall",grant,order(),now));
  PurchaseFacts existing=receipt("old-order",now-20000,true);yes(!s.reconcile("com.taobao.taobao",existing,now),"old order accepted");yes(!s.reconcile("com.jingdong.app.mall",receipt("new-order",now,true),now),"other merchant receipt accepted");PurchaseFacts wrong=receipt("new-order",now,false);wrong.total=501;yes(!s.reconcile("com.taobao.taobao",wrong,now),"wrong total accepted");
  yes(s.reconcile("com.taobao.taobao",receipt("new-order",now,false),now)&&s.state.equals(PurchaseState.ORDER_VERIFIED),"new order receipt not bound");yes(!s.paidFor("run1"),"created order counted as paid");reject(()->s.armSubmit("run1","com.taobao.taobao",grant,order(),now));
  PurchaseFacts cashier=receipt("new-order",now,false);cashier.cashier=true;cashier.total=500;reject(()->s.armPay("run1","com.taobao.taobao",grant,cashier,now));cashier.total=499;cashier.orderKey=PurchaseFacts.digest("other-order");reject(()->s.armPay("run1","com.taobao.taobao",grant,cashier,now));cashier.orderKey=PurchaseFacts.digest("new-order");s.armPay("run1","com.taobao.taobao",grant,cashier,now);yes(s.pending(),"payment not write-ahead");reject(()->s.armPay("run1","com.taobao.taobao",grant,cashier,now));yes(!s.reconcile("com.taobao.taobao",receipt("other-order",now,true),now),"wrong paid order accepted");
  yes(s.reconcile("com.taobao.taobao",receipt("new-order",now,true),now)&&s.paidFor("run1"),"paid receipt not accepted");yes(!s.paidFor("run2"),"other goal reused payment success");reject(()->s.armSubmit("run1","com.taobao.taobao",grant,order(),now));s.armSubmit("run2","com.taobao.taobao",grant,order(),now+1000);yes(!s.reconcile("com.taobao.taobao",receipt("new-order",now,true),now+1000),"previous order reused for new goal");
  PurchaseState direct=new PurchaseState();direct.armSubmit("combined","com.taobao.taobao",grant,order(),now);yes(direct.reconcile("com.taobao.taobao",receipt("combined-order",now,true),now)&&direct.paidFor("combined"),"combined submit/pay receipt lost");System.out.println("PASS: "+n+" one-order write-ahead and native payment receipt transitions");}
}
